import React, { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';
import ReviewsSection from '../ReviewsSection';
import { PublicVideoCard } from './PublicProfileShared';
import { getHealthcareSubcategory, getLocationText, getWebsiteUrl, getWhatsAppUrl, normalizeList } from '../../utils/healthcare';

const valueFrom = (place, ...keys) => {
  const profile = place?.attributes?.businessProfile || {};
  for (const source of [profile.categorySpecific, profile.common, place?.attributes]) {
    for (const key of keys) {
      const value = source?.[key];
      if (value !== undefined && value !== null && value !== '') return value;
    }
  }
  return null;
};

const listFrom = (place, ...keys) => {
  const value = valueFrom(place, ...keys);
  if (Array.isArray(value)) return value.filter(Boolean);
  return normalizeList(value || []);
};
const peopleFrom = (place, ...keys) => {
  const people = valueFrom(place, ...keys);
  if (!Array.isArray(people)) return [];
  return people.map((person) => typeof person === 'string' ? { name: person } : person).filter((person) => person?.name || person?.title);
};
const locationFor = (place) => {
  const entries = [
    place.address,
    getLocationText(place.location?.area),
    getLocationText(place.location?.city),
    getLocationText(place.location?.district),
    getLocationText(place.location?.state),
  ];
  const seen = new Set();
  return entries
    .filter(Boolean)
    .flatMap((entry) => String(entry).split(','))
    .map((part) => part.trim())
    .filter((part) => {
      const key = part.toLocaleLowerCase();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .join(', ');
};
const imageFor = (item) => typeof item === 'string' ? item : item?.image || item?.url || item?.photo || '';
const imageListFor = (place) => {
  const gallery = place.images?.length ? place.images : valueFrom(place, 'gallery', 'galleryPhotos', 'clinicPhotos', 'hospitalPhotos', 'gymPhotos');
  return (Array.isArray(gallery) ? gallery : []).map(imageFor).filter(Boolean).slice(0, 12);
};

function PageSection({ id, label, title, children, className = '' }) {
  return <section id={id} className={`scroll-mt-24 px-4 py-12 sm:px-6 lg:px-8 ${className}`}><div className="mx-auto max-w-7xl"><p className="text-xs font-extrabold uppercase tracking-[.18em] text-teal-700">{label}</p><h2 className="mt-2 text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">{title}</h2><div className="mt-6">{children}</div></div></section>;
}

