    <path d="M11.1 10.6c.4-.5 1.2-.5 1.6 0l1.4 2.1c.3.4.2.9-.1 1.2l-.8.8a9.6 9.6 0 0 0 4.1 4.1l.8-.8c.3-.3.8-.4 1.2-.1l2.1 1.4c.5.4.5 1.2 0 1.6-.8.8-2 1.1-3.1.8a13.5 13.5 0 0 1-7.9-7.9c-.3-1.1 0-2.3.7-3.2Z" />
